import React, { useContext } from "react";
import { Button, Form, Grid, Header, Segment } from "semantic-ui-react";
import appContext from "../../appContext";
import configuration from "../../utils/storage";
import { Octokit } from "octokit";

const Config = () => {
  const { apiKey, setApiKey, owner, setOwner, repo, setRepo, setData } =
    useContext(appContext);

  const handleFetch = async () => {
    configuration.apiKey = apiKey;
    configuration.owner = owner;
    configuration.repo = repo;
    configuration.save();

    const octokit = new Octokit({
      auth: apiKey,
    });

    const response = await octokit.request("GET /repos/{owner}/{repo}/pulls", {
      owner: owner,
      repo: repo,
      headers: {
        "X-GitHub-Api-Version": "2022-11-28",
      },
    });

    if (response.data) {
      setData(response.data);
      configuration.data = response.data
      configuration.save()
    }
  };

  const handleOldData = () => {
    setData(configuration.data)
  }

  return (
    <>
      <Grid.Column style={{ maxWidth: 450 }}>
        <Header as="h2" color="teal" textAlign="center">
          Configuration
        </Header>
        <Form size="large">
          <Segment stacked>
            <Form.Input
              fluid
              icon="github"
              iconPosition="left"
              placeholder="GITHUB API KEY"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
            />
            <Form.Input
              fluid
              icon="user secret"
              iconPosition="left"
              placeholder="OWNER"
              value={owner}
              onChange={(e) => setOwner(e.target.value)}
            />
            <Form.Input
              fluid
              icon="beer"
              iconPosition="left"
              placeholder="REPO"
              value={repo}
              onChange={(e) => setRepo(e.target.value)}
            />

            {configuration.data.length ? <Button.Group size='large'>
              <Button onClick={handleFetch}>Fetch</Button>
              <Button.Or />
              <Button primary onClick={handleOldData}>Old Data</Button>
            </Button.Group> : <Button primary size='large' onClick={handleFetch}>Fetch</Button>}
            
          </Segment>
        </Form>
      </Grid.Column>
    </>
  );
};

export default Config;
