import React, { useContext, useState } from "react";
import { Header, Image, Table, Grid, Button, Icon } from "semantic-ui-react";
import appContext from "../../appContext";
import { Octokit } from 'octokit'
import configuration from "../../utils/storage";

const PullRequests = () => {
  const { data } = useContext(appContext);
  const [loading, setLoading] = useState(false);

  const approve = (number) => () => {
    setLoading(number)

    const octokit = new Octokit({
      auth: configuration.apiKey
    })
    
    octokit.request('POST /repos/{owner}/{repo}/pulls/{pull_number}/reviews', {
      owner: configuration.owner,
      repo: configuration.repo,
      pull_number: number,
      event: 'APPROVE',
      headers: {
        'X-GitHub-Api-Version': '2022-11-28'
      }
    }).then(() => {
      setLoading(false)
    })
  }

  return (
    <>
      <Grid.Column style={{ maxWidth: 1080 }}>
        <Table basic="very" celled collapsing>
          <Table.Header>
            <Table.Row>
              <Table.HeaderCell>Author</Table.HeaderCell>
              <Table.HeaderCell>Title</Table.HeaderCell>
              <Table.HeaderCell>Actions</Table.HeaderCell>
            </Table.Row>
          </Table.Header>

          <Table.Body>
            {data.map(item => {

              return <Table.Row>
              <Table.Cell>
                <Header as="h4" image>
                  <Image
                    src={item.user.avatar_url}
                    rounded
                    size="mini"
                  />
                  <Header.Content>
                    {item.user.login}
                  </Header.Content>
                </Header>
              </Table.Cell>
              <Table.Cell>
                <a href={item.html_url} target="_blank" rel="noreferrer">
                  #{item.number} {item.title}
                </a>
              </Table.Cell>
              <Table.Cell>
                <Button color='green' onClick={approve(item.number)}>Approve</Button> {loading === item.number && <Icon loading name='spinner' />}
              </Table.Cell>
            </Table.Row>
            })}
          </Table.Body>
        </Table>
      </Grid.Column>
    </>
  );
};

export default PullRequests;
