export const json_parse = (data) => {
  try {
    if (!data) return {data: []}

    return JSON.parse(data)
  } catch {
    return {
      data: [],
    }
  }
}

class MyStorage {
  constructor() {
    this.reload()
  }

  load(data) {
    Object.keys(data).forEach(key => {
      this[key] = data[key]
    })
  }

  reload() {
    const data = json_parse(sessionStorage.getItem("configuration"))
    this.load(data)
  }

  save = () => {
    sessionStorage.setItem("configuration", JSON.stringify(this))
    this.load(this)
  }
}

const configuration = new MyStorage()

export default configuration
