import React, { useState } from "react";
import {
  Grid,
} from "semantic-ui-react";
import configuration from "./utils/storage";
import AppContext from "./appContext";
import Config from './components/Config'
import PullRequests from './components/PullRequests'

const App = () => {
  const [apiKey, setApiKey] = useState(configuration.apiKey)
  const [owner, setOwner] = useState(configuration.owner)
  const [repo, setRepo] = useState(configuration.repo)
  const [data, setData] = useState([])

  const initialState = {
    data,
    apiKey,
    owner,
    repo,
    setApiKey,
    setRepo,
    setOwner,
    setData
  }

  return (
    <AppContext.Provider value={initialState}>
      <div className="App">
        <Grid
          textAlign="center"
          style={{ height: "100vh" }}
          verticalAlign="middle"
        >
          {data.length ? <PullRequests/> : <Config/>}
        </Grid>
      </div>
    </AppContext.Provider>
  );
};

export default App;
